import { Eraser, Paintbrush, Pause, Play, RotateCcw, TriangleAlert } from 'lucide-react';
import { useEffect, useRef } from 'react';
import { useGameContext } from '@/context/GameContext';
import { useLanguageServiceContext } from '@/context/LanguageServiceContext';
import { CANVAS_DIMS } from '@/lib/canvas';
import type { Location } from '@/lib/types';
import { cn } from '@/lib/utils';

const BRUSHES = [1, 2, 3, 5];

function brushCells(center: Location, size: number): Location[] {
  const r = size - 1;
  const cells: Location[] = [];
  for (let dy = -r; dy <= r; dy++)
    for (let dx = -r; dx <= r; dx++)
      if (dx * dx + dy * dy <= r * r + r) cells.push({ x: center.x + dx, y: center.y + dy });
  return cells;
}

function Canvas() {
  const { canvasRef, paint, strokeSize, tool, runtimeError, elements, clear } = useGameContext();
  const { status } = useLanguageServiceContext();
  const last = useRef<Location | null>(null);

  const toGrid = (event: React.PointerEvent<HTMLCanvasElement>): Location => {
    const rect = event.currentTarget.getBoundingClientRect();
    return {
      x: Math.floor(((event.clientX - rect.left) * CANVAS_DIMS.x) / rect.width),
      y: Math.floor(((event.clientY - rect.top) * CANVAS_DIMS.y) / rect.height),
    };
  };

  const stroke = (event: React.PointerEvent<HTMLCanvasElement>) => {
    const drawing = (event.buttons & 1) !== 0;
    const erasing = (event.buttons & 2) !== 0 || (drawing && tool === 'erase');
    if (!drawing && !erasing) {
      last.current = null;
      return;
    }
    const point = toGrid(event);
    const from = last.current ?? point;
    const steps = Math.max(Math.abs(point.x - from.x), Math.abs(point.y - from.y), 1);
    const seen = new Set<string>();
    const cells: Location[] = [];
    for (let i = 1; i <= steps; i++) {
      const c = {
        x: Math.round(from.x + ((point.x - from.x) * i) / steps),
        y: Math.round(from.y + ((point.y - from.y) * i) / steps),
      };
      for (const cell of brushCells(c, strokeSize)) {
        const key = `${cell.x},${cell.y}`;
        if (!seen.has(key)) {
          seen.add(key);
          cells.push(cell);
        }
      }
    }
    paint(cells, erasing);
    last.current = point;
  };

  const empty = elements.length === 0;

  return (
    <div className="relative aspect-square w-full overflow-hidden rounded-xl bg-stage shadow-stage dark:ring-1 dark:ring-white/8">
      <canvas
        ref={canvasRef}
        width={CANVAS_DIMS.x}
        height={CANVAS_DIMS.y}
        aria-label="Sandbox grid. Paint with the left mouse button, erase with the right."
        className={cn(
          'absolute inset-0 size-full touch-none [image-rendering:pixelated]',
          tool === 'erase' ? 'cursor-cell' : 'cursor-crosshair',
        )}
        onPointerDown={(e) => {
          e.currentTarget.setPointerCapture(e.pointerId);
          last.current = null;
          stroke(e);
        }}
        onPointerMove={stroke}
        onPointerUp={() => (last.current = null)}
        onContextMenu={(e) => e.preventDefault()}
      />
      {empty && !runtimeError && (
        <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center gap-2 px-10 text-center">
          <p className="text-base font-semibold text-stage-foreground">
            {status === 'error' ? 'Fix the problem in your code, then press Run' : 'Press Run to bring your world to life'}
          </p>
          <p className="max-w-xs text-sm text-stage-foreground/60">
            Then pick an element below and paint here. Right-click erases.
          </p>
        </div>
      )}
      {runtimeError && (
        <div role="alert" className="absolute inset-x-3 bottom-3 rounded-xl bg-background/95 p-4 shadow-lg">
          <p className="flex items-center gap-2 text-sm font-semibold text-destructive">
            <TriangleAlert className="size-4" /> {runtimeError.title}
          </p>
          <p className="mt-1 text-sm text-foreground/85">{runtimeError.hint}</p>
          <button type="button" onClick={clear} className="btn-quiet mt-3 h-8 px-3 text-sm">
            <RotateCcw className="size-3.5" /> Start over
          </button>
        </div>
      )}
    </div>
  );
}

function Palette() {
  const { elements, element, setElement, tool, setTool } = useGameContext();
  if (elements.length === 0) return null;
  return (
    <div role="radiogroup" aria-label="Element to paint" className="flex flex-wrap gap-1.5">
      {elements.map((e, i) => {
        const selected = tool === 'paint' && e.name === element;
        return (
          <button
            key={e.name}
            type="button"
            role="radio"
            aria-checked={selected}
            title={i < 9 ? `Press ${i + 1}` : undefined}
            onClick={() => {
              setElement(e.name);
              setTool('paint');
            }}
            className={cn(
              'chip inline-flex h-8 items-center gap-2 rounded-lg border pr-3 pl-1.5 text-[13px] font-medium',
              selected ? 'border-foreground/80 bg-foreground text-background' : 'border-border bg-card hover:bg-muted',
            )}
          >
            <span className="size-5 rounded-[5px] ring-1 ring-black/10 ring-inset" style={{ background: e.color }} />
            {e.name}
          </button>
        );
      })}
    </div>
  );
}

function Tools() {
  const { strokeSize, setStrokeSize, tool, setTool, paused, setPaused, clear, pixelCount, elements } =
    useGameContext();
  const disabled = elements.length === 0;
  return (
    <div className="flex flex-wrap items-center gap-2">
      <div className="segmented" role="group" aria-label="Tool">
        <button type="button" aria-pressed={tool === 'paint'} onClick={() => setTool('paint')} title="Paint">
          <Paintbrush className="size-4" />
          <span className="sr-only">Paint</span>
        </button>
        <button type="button" aria-pressed={tool === 'erase'} onClick={() => setTool('erase')} title="Erase">
          <Eraser className="size-4" />
          <span className="sr-only">Erase</span>
        </button>
      </div>
      <div className="segmented" role="group" aria-label="Brush size">
        {BRUSHES.map((size) => (
          <button
            key={size}
            type="button"
            aria-pressed={strokeSize === size}
            onClick={() => setStrokeSize(size)}
            title={`Brush size ${size}`}
          >
            <span className="rounded-full bg-current" style={{ width: 3 + size * 2.2, height: 3 + size * 2.2 }} />
            <span className="sr-only">Brush size {size}</span>
          </button>
        ))}
      </div>
      <div className="ml-auto flex items-center gap-2">
        <span className="text-xs text-muted-foreground tabular-nums" aria-live="off">
          {pixelCount.toLocaleString('en-US')} pixels
        </span>
        <button type="button" className="btn-quiet h-8 px-2.5" disabled={disabled} onClick={() => setPaused(!paused)}>
          {paused ? <Play className="size-4" /> : <Pause className="size-4" />}
          {paused ? 'Play' : 'Pause'}
        </button>
        <button type="button" className="btn-quiet h-8 px-2.5" disabled={disabled} onClick={clear}>
          <RotateCcw className="size-4" /> Clear
        </button>
      </div>
    </div>
  );
}

export default function StagePanel() {
  const { elements, setElement, setTool } = useGameContext();

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      if (target?.closest('textarea, input, [contenteditable]')) return;
      const n = Number(e.key);
      if (n >= 1 && n <= 9 && elements[n - 1]) {
        setElement(elements[n - 1].name);
        setTool('paint');
      } else if (e.key === 'e') setTool('erase');
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [elements, setElement, setTool]);

  return (
    <section aria-label="Sandbox" className="flex min-h-0 flex-col gap-3 overflow-y-auto bg-background p-4">
      <Canvas />
      <Tools />
      <Palette />
      {elements.length > 0 && (
        <p className="text-xs text-muted-foreground">
          Left-click paints. Right-click erases.{' '}
          {elements.length > 1 ? `Keys 1–${Math.min(elements.length, 9)} pick an element.` : ''}
        </p>
      )}
    </section>
  );
}
